// === Sub-type detection ===
function getHarfSubType(word, bare) {
  if (HARF_JAR.has(word) || HARF_JAR.has(bare)) return 'حرف جر';
  if (HARF_ATF.has(word) || HARF_ATF.has(bare)) return 'حرف عطف';
  if (HARF_NAFY.has(word) || HARF_NAFY.has(bare)) return 'حرف نفی';
  if (HARF_ISTIFHAM.has(word) || HARF_ISTIFHAM.has(bare)) return 'حرف استفہام';
  if (HARF_TAKID.has(word) || HARF_TAKID.has(bare)) return 'حرف تاکید';
  if (HARF_SHART.has(word) || HARF_SHART.has(bare)) return 'حرف شرط';
  if (HARF_NIDA.has(word) || HARF_NIDA.has(bare)) return 'حرف ندا';
  return 'حرف';
}

function getVerbSubType(word, bare) {
  // Detect tense based on patterns
  if (/^(يَ|تَ|أُ|نَ|يُ|تُ|أَ|نُ)/.test(word)) return 'فعل مضارع';
  if (/^(اِ|اُ|افْعَلْ|افْعُلْ|فَعَلْ|فَعِلْ|فَعُلْ)/.test(word) && !word.endsWith('َ')) return 'فعل امر';
  // Past tense indicators
  if (word.endsWith('َ') || word.endsWith('ُوا') || word.endsWith('َتْ') || word.endsWith('ْتَ') || word.endsWith('ْنَا') || word.endsWith('ْتُمْ')) return 'فعل ماضی';
  if (COMMON_VERB_WORDS.has(word) && !word.startsWith('ي') && !word.startsWith('ت') && !word.startsWith('اِ') && !word.startsWith('اُ')) return 'فعل ماضی';
  return 'فعل';
}

function getIsmSubType(word, bare, en) {
  // Detect specific noun sub-types
  if (/\.$/.test(en) || /name|Allah|God|Lord/i.test(en)) return 'اسم علم';
  if (/(ing|er)\b/i.test(en) && /one who|the/i.test(en)) return 'اسم فاعل';
  if (/(ed|en)\b/i.test(en) && /one who|the/i.test(en)) return 'اسم مفعول';
  if (word.endsWith('ة') || word.endsWith('َة') || word.endsWith('َٰة')) return 'اسم (تاء مربوطہ)';
  if (word.startsWith('ال')) return 'اسم معرفہ';
  if (/(ity|ness|tion|sion)\b/i.test(en)) return 'اسم مصدر';
  if (/(plural|all|every|each|some|whole)\b/i.test(en)) return 'اسم (جمع/کلی)';
  return 'اسم';
}

// === Main Classifier ===
export function classifyWord(ar, en = '') {
  const word = (ar || '').trim();
  const bare = word.replace(/[ًٌٍَُِّْـ]/g, '');

  // Check exact matches first
  if (ALL_HUROOF.has(word) || ALL_HUROOF.has(bare)) {
    const subType = getHarfSubType(word, bare);
    if (HARF_SHART.has(word) || HARF_SHART.has(bare)) {
      return { type: 'shart', subType: 'حرف شرط' };
    }
    return { type: 'harf', subType };
  }

  if (ZAMEER_MUNFASIL.has(word) || ZAMEER_MUNFASIL.has(bare)) {
    return { type: 'zameer', subType: 'ضمیر منفصل' };
  }

  if (ISM_ISHAARAH.has(word) || ISM_ISHAARAH.has(bare)) {
    return { type: 'ishaarah', subType: 'اسم اشارة' };
  }

  if (ISM_MOOSOOL.has(word) || ISM_MOOSOOL.has(bare)) {
    return { type: 'moosool', subType: 'اسم موصول' };
  }

  if (COMMON_VERB_WORDS.has(word) || COMMON_VERB_WORDS.has(bare)) {
    return { type: 'fail', subType: getVerbSubType(word, bare) };
  }

  // Pattern-based verb detection: starts with ي/ت/أ/ن + has verbal pattern
  if (/^(يَ|تَ|أُ|نَ|يُ|تُ)/.test(word) && word.length > 3) {
    // Check if it looks like a present tense verb (يَفْعَلُ, تَفْعَلُ, etc.)
    if (/^(يَ|تَ|نَ)[َُِ][ْ]?[ا-ي]/.test(word) && !word.startsWith('ال')) {
      return { type: 'fail', subType: 'فعل مضارع' };
    }
  }

  // Pattern-based verb detection: imperative (starts with اِ or اُ + consonant)
  if (/^(اِ|اُ)[ْ]?[ا-ي]/.test(word) && word.length > 3 && !word.startsWith('ال') && !word.startsWith('إِنْ') && !word.startsWith('إِذَا')) {
    // Could be imperative or form VIII verb
    if (word.endsWith('ْ') || word.endsWith('ُوا')) {
      return { type: 'fail', subType: 'فعل امر' };
    }
  }

  // Past tense verb: 3-letter root + fatha pattern (فَعَلَ, فَعِلَ, فَعُلَ)
  if (/^[ا-ي][َُِ][ا-ي][َُِ][ا-ي]َ?$/.test(word) && word.length >= 4 && !word.startsWith('ال')) {
    // Check if it's not a known noun
    if (!word.endsWith('ة') && !word.endsWith('َة')) {
      return { type: 'fail', subType: 'فعل ماضی' };
    }
  }

  // Default: noun (اسم)
  return { type: 'ism', subType: getIsmSubType(word, bare, en) };
}

// Get grammar type metadata
export function getGrammarTypeMeta(typeId) {
  return GRAMMAR_TYPES[typeId] || GRAMMAR_TYPES.ism;
}

// ───────── lib/quranDictionaryData.js ─────────
// Quran Dictionary — authentic vocabulary from the Holy Quran
// Sourced from Uthmani Quran text and Quranic Arabic Corpus frequency data
// Each entry: { ar, ur, en, count }
// Frequency categories based on occurrence count in the Quran




// Frequency category thresholds:
// most_frequent:     500+ occurrences
// very_frequent:      200-499 occurrences
// frequently_used:    100-199 occurrences
// medium_frequency:   50-99 occurrences
// low_frequency:      10-49 occurrences
// rare:               2-9 occurrences
