// Arabic alphabet order for sorting
export const ARABIC_ALPHABET = [
  'ا', 'ب', 'ت', 'ث', 'ج', 'ح', 'خ', 'د', 'ذ', 'ر', 'ز', 'س', 'ش', 'ص', 'ض',
  'ط', 'ظ', 'ع', 'غ', 'ف', 'ق', 'ك', 'ل', 'م', 'ن', 'ه', 'و', 'ي', 'ء', 'أ', 'إ', 'آ', 'ؤ', 'ئ', 'ة', 'ى'
];

// Get the first Arabic letter of a word (stripping leading "ال" prefix)
export function getArabicLetter(word) {
  let w = word.replace(/^(ال|وَال|فَال|بِال|كَال|لِل|لِلْ)/, '').replace(/[ًٌٍَُِّْ]/g, '');
  return w.charAt(0) || word.charAt(0);
}

// Determine frequency category from count
export function getFrequencyCategory(count) {
  if (count >= 500) return 'most_frequent';
  if (count >= 200) return 'very_frequent';
  if (count >= 100) return 'frequently_used';
  if (count >= 50) return 'medium_frequency';
  if (count >= 10) return 'low_frequency';
  if (count >= 2) return 'rare';
  return 'hapax';
}

export const FREQUENCY_CATEGORIES = [
  { id: 'most_frequent', title: 'سب سے زیادہ', titleEn: 'Most Frequent (500+)', color: 'bg-red-500/15 text-red-800 border-red-300' },
  { id: 'very_frequent', title: 'بہت زیادہ', titleEn: 'Very Frequent (200-499)', color: 'bg-orange-100 text-orange-800 border-orange-300' },
  { id: 'frequently_used', title: 'اکثر', titleEn: 'Frequently Used (100-199)', color: 'bg-amber-500/15 text-amber-800 border-amber-300' },
  { id: 'medium_frequency', title: 'درمیانی', titleEn: 'Medium Frequency (50-99)', color: 'bg-yellow-100 text-yellow-800 border-yellow-300' },
  { id: 'low_frequency', title: 'کم', titleEn: 'Low Frequency (10-49)', color: 'bg-green-100 text-green-800 border-green-300' },
  { id: 'rare', title: 'نایاب', titleEn: 'Rare (2-9)', color: 'bg-blue-100 text-blue-800 border-blue-300' },
  { id: 'hapax', title: 'ایک بار', titleEn: 'Hapax Legomena (Once)', color: 'bg-purple-100 text-purple-800 border-purple-300' },
];

// Build the full dictionary: deduplicate, assign serial, letter, category, sort
export function buildDictionary() {
  // Filter out non-Quranic constructions (phrases not found in the Quran as standalone)
  const QURANIC_WITNESS_PHRASES = [
    'Witness', 'Your witness', 'Their witness', 'Witness against himself',
    'Witness over your deeds', 'Witness over their deeds',
    'Witness between you', 'Witness between them', 'Clear witness',
  ];
  const filteredWords = DICTIONARY_WORDS.filter(w => {
    if (w.en && w.en.startsWith('Witness over') && !QURANIC_WITNESS_PHRASES.includes(w.en)) return false;
    if (w.en && w.en.startsWith('Witness on the')) return false;
    return true;
  });
  const seen = new Map();
  for (const w of filteredWords) {
    const key = w.ar.replace(/[ًٌٍَُِّْ]/g, '');
    if (!seen.has(key) || seen.get(key).count < w.count) {
      seen.set(key, w);
    }
  }
  const unique = Array.from(seen.values());
  // Sort by Arabic letter first, then by count descending
  unique.sort((a, b) => {
    const la = getArabicLetter(a.ar);
    const lb = getArabicLetter(b.ar);
    const ia = ARABIC_ALPHABET.indexOf(la);
    const ib = ARABIC_ALPHABET.indexOf(lb);
    if (ia !== ib) return (ia === -1 ? 999 : ia) - (ib === -1 ? 999 : ib);
    return b.count - a.count;
  });
  return unique.map((w, i) => {
    const grammar = classifyWord(w.ar, w.en);
    return {
      ...w,
      serial_no: i + 1,
      arabic_letter: getArabicLetter(w.ar),
      frequency_category: getFrequencyCategory(w.count),
      grammar_type: grammar.type,
      grammar_subtype: grammar.subType,
    };
  });
}

// Look up a single Quranic word (any vowelisation) in the dictionary → { ar, ur, en, count } | null
let _lookup = null;
const dictKey = (t = '') => t.replace(/[\u0610-\u061A\u064B-\u065F\u0670\u06D6-\u06ED\u0640]/g, '').replace(/[إأآٱ]/g, 'ا').replace(/ى/g, 'ي').replace(/ة/g, 'ه');
export function lookupDictionaryWord(arabic) {
  if (!_lookup) {
    _lookup = new Map();
    for (const w of buildDictionary()) {
      const k = dictKey(w.ar);
      if (!_lookup.has(k) || _lookup.get(k).count < w.count) _lookup.set(k, w);
    }
  }
  return _lookup.get(dictKey(arabic)) || null;
}
